create table if not exists public.tasks (id uuid primary key default gen_random_uuid(),title text not null,owner text not null default 'Unassigned',status text not null default 'Backlog' check (status in ('Backlog','In Progress','Review','Done')),priority text not null default 'Medium' check (priority in ('Low','Medium','High','Critical')),created_at timestamptz not null default now());